const log = createLogger('WorkspaceProvisioning');

type WorkspaceProvisioningDeps = {
  store: SessionStore;
  inventory: WorkspaceInventory;
  worktreeManager: WorktreeManagerLike;
  telemetry: VariantsTelemetry;
  resolveProjectEnvironment: (sessionId: string) => Promise<ProjectEnvironment>;
  installDependencies: (
    worktreePath: string,
    options?: { workspaceRoot: string; force?: boolean; signal?: AbortSignal },
  ) => Promise<void>;
  provisionTimeoutMs: number;
  cancelSession: (sessionId: string) => Promise<unknown>;
  changed: () => void;
  isSessionLive: (sessionId: string) => boolean;
};

class ProvisionTimeoutError extends Error {}

const withProvisionTimeout = <T>(
  work: Promise<T>,
  timeoutMs: number,
): Promise<T> => {
  let timer: NodeJS.Timeout;
  const timeout = new Promise<never>((_, reject) => {
    timer = setTimeout(() => reject(new ProvisionTimeoutError()), timeoutMs);
    timer.unref?.();
  });
  return Promise.race([work, timeout]).finally(() => clearTimeout(timer));
};

const SENSITIVE_PATH_SEGMENTS = new Set([
  '.ssh',
  '.aws',
  '.gnupg',
  '.kube',
  '.docker',
  '.config',
  '.npm',
  '.cargo',
  '.gem',
  '.netrc',
  'private',
  'secrets',
  'credentials',
]);

const hasSensitivePathSegment = (absolutePath: string): boolean =>
  absolutePath
    .split(/[/\\]/)
    .filter(Boolean)
    .some((segment) => SENSITIVE_PATH_SEGMENTS.has(segment.toLowerCase()));

const copyAssetIntoWorktree = (
  worktreePath: string,
  entry: AssetPlanEntry,
  assetSourceRoot: string | undefined,
): void => {
  if (!assetSourceRoot) {
    throw new AgentVariantsError(
      'RUNTIME_VALIDATION_FAILED',
      `assetPlan.source requires an approved asset root before copying '${entry.source}'`,
    );
  }
  if (!path.isAbsolute(assetSourceRoot)) {
    throw new AgentVariantsError(
      'RUNTIME_VALIDATION_FAILED',
      `assetSourceRoot must be an absolute path, got '${assetSourceRoot}'`,
    );
  }
  const absoluteSource = path.isAbsolute(entry.source)
    ? entry.source
    : path.resolve(assetSourceRoot, entry.source);
  const extension = path.extname(absoluteSource).toLowerCase();
  if (!ALLOWED_INERT_ASSET_EXTENSIONS.has(extension)) {
    throw new AgentVariantsError(
      'RUNTIME_VALIDATION_FAILED',
      `assetPlan.source extension '${extension || '(none)'}' is not on the allowlist (got '${entry.source}'). Only inert media/font/document assets may be copied.`,
    );
  }
  let sourceStat: fs.Stats;
  try {
    sourceStat = fs.lstatSync(absoluteSource);
  } catch {
    throw new AgentVariantsError(
      'RUNTIME_VALIDATION_FAILED',
      `assetPlan.source not found on disk: ${entry.source}`,
    );
  }
  if (sourceStat.isSymbolicLink()) {
    throw new AgentVariantsError(
      'RUNTIME_VALIDATION_FAILED',
      `assetPlan.source must not be a symlink: ${entry.source}`,
    );
  }
  if (!sourceStat.isFile()) {
    throw new AgentVariantsError(
      'RUNTIME_VALIDATION_FAILED',
      `assetPlan.source must be a regular file: ${entry.source}`,
    );
  }
  let resolvedSource: string;
  try {
    resolvedSource = fs.realpathSync(absoluteSource);
  } catch {
    throw new AgentVariantsError(
      'RUNTIME_VALIDATION_FAILED',
      `assetPlan.source could not be resolved: ${entry.source}`,
    );
  }
  let resolvedRoot: string;
  try {
    resolvedRoot = fs.realpathSync(assetSourceRoot);
  } catch {
    throw new AgentVariantsError(
      'RUNTIME_VALIDATION_FAILED',
      `assetSourceRoot could not be resolved: ${assetSourceRoot}`,
    );
  }
  if (!fs.statSync(resolvedSource).isFile()) {
    throw new AgentVariantsError(
      'RUNTIME_VALIDATION_FAILED',
      `assetPlan.source resolved target must be a regular file: ${entry.source}`,
    );
  }
  if (!isPathWithinRoot(resolvedRoot, resolvedSource)) {
    throw new AgentVariantsError(
      'RUNTIME_VALIDATION_FAILED',
      `assetPlan.source must stay inside the approved asset root: ${entry.source}`,
    );
  }
  if (hasSensitivePathSegment(path.relative(resolvedRoot, resolvedSource))) {
    throw new AgentVariantsError(
      'RUNTIME_VALIDATION_FAILED',
      `assetPlan.source traverses a sensitive directory and is refused: ${entry.source}`,
    );
  }
  const resolvedExtension = path.extname(resolvedSource).toLowerCase();
  if (!ALLOWED_INERT_ASSET_EXTENSIONS.has(resolvedExtension)) {
    throw new AgentVariantsError(
      'RUNTIME_VALIDATION_FAILED',
      `assetPlan.source resolved extension '${resolvedExtension || '(none)'}' is not on the allowlist (resolved from '${entry.source}').`,
    );
  }
  const destination = path.join(worktreePath, entry.destination);
  if (
    path.isAbsolute(entry.destination) ||
    !isPathWithinRoot(worktreePath, destination)
  ) {
    throw new AgentVariantsError(
      'RUNTIME_VALIDATION_FAILED',
      `assetPlan.destination must stay inside the worktree, got '${entry.destination}'`,
    );
  }
  fs.mkdirSync(path.dirname(destination), { recursive: true });
  fs.copyFileSync(resolvedSource, destination);
};

export class WorkspaceProvisioning {
  private readonly deps: WorkspaceProvisioningDeps;

  constructor(deps: WorkspaceProvisioningDeps) {
    this.deps = deps;
  }

  async resolveContextAssetPreviewKind(sessionId: string): Promise<void> {
    try {
      const environment = await this.deps.resolveProjectEnvironment(sessionId);
      this.deps.inventory.setContextAssetPreviewKind(
        sessionId,
        environment.framework === 'static' ? 'static_artifact' : 'dev_server',
      );
    } catch (error) {
      this.deps.inventory.setContextAssetPreviewKind(sessionId, 'dev_server');
      log.warn(
        `Failed to resolve context asset preview kind for ${sessionId}; using dev-server references`,
        error,
      );
    }
  }

  assignImplementationWorkspaces(
    sessionId: string,
    items: RequestWorkResult['leasedWorkItems'],
  ): void {
    this.deps.inventory.openSession(sessionId);
    const projectContext = this.deps.store.getProjectContext(sessionId);
    const provisionStartedAt = Date.now();
    let assignedCount = 0;
    for (const item of items) {
      if (item.kind === 'static_preview' || item.kind === 'refine_variant') {
        if (!this.deps.inventory.getAssignedWorkspace(sessionId, item.id)) {
          assignedCount += 1;
          const input = this.deps.store.requireVariantWorkItemInput({
            sessionId,
            workItemId: item.id,
            kinds: [item.kind],
          });
          const existingProjectPath =
            projectContext.kind === 'existing'
              ? projectContext.projectPath
              : undefined;
          const existingParent =
            existingProjectPath && fs.existsSync(existingProjectPath)
              ? path.join(
                  existingProjectPath,
                  '.rivet',
                  'variant-work',
                  sessionId,
                )
              : path.join(os.tmpdir(), 'rivet-variant-work', sessionId);
          const parent =
            projectContext.kind === 'fresh'
              ? projectContext.workspacePath
              : existingParent;
          const rootPath =
            projectContext.kind === 'fresh'
              ? path.join(parent, `.rivet-preview-${item.id}`)
              : path.join(parent, item.id);
          const sourceVariantId = input.sourceVariantId ?? input.variantId;
          const sourcePreview = sourceVariantId
            ? this.deps.inventory.getStaticPreview(sessionId, sourceVariantId)
            : undefined;
          const sourceInput = sourceVariantId
            ? this.deps.store.getVariantWorkItemInput(
                sessionId,
                sourceVariantId,
              )
            : undefined;
          const previewRoutes =
            input.previewRoutes ?? sourceInput?.previewRoutes;
          this.deps.inventory.assignArtifactWorkspace({
            sessionId,
            workItemId: item.id,
            rootPath,
            allowedRoot: parent,
            entryPath: staticPreviewPagePath({
              entryPath:
                previewRoutes?.length && sourcePreview
                  ? sourcePreview.entryPath
                  : 'index.html',
              routePath: previewRoutes?.[0],
            }),
            sourceDirectory: sourcePreview?.assetBase,
            seedHtml: input.currentHtml,
          });
        }
      }
      if (!isVariantWorkItemKind(item.kind)) continue;
      const input = this.deps.store.requireVariantWorkItemInput({
        sessionId,
        workItemId: item.id,
        kinds: [item.kind],
      });
      const assets = input.context?.contextAssets ?? [];
      if (assets.length === 0) continue;
      const workspace = this.deps.inventory.getAssignedWorkspace(
        sessionId,
        item.id,
      );
      if (!workspace) {
        throw new AgentVariantsError(
          'RUNTIME_VALIDATION_FAILED',
          `Variant ${item.id} has no assigned workspace`,
        );
      }
      const previewKind =
        workspace.kind === 'artifact_directory'
          ? 'static_artifact'
          : (this.deps.inventory.getContextAssetPreviewKind(sessionId) ??
            'dev_server');
      this.deps.inventory.setContextAssets(
        sessionId,
        item.id,
        materializeContextAssets({ assets, workspace, previewKind }),
      );
    }
    if (assignedCount > 0) {
      this.deps.telemetry.track('agent_variants.provisioning_completed', {
        source: 'mcp',
        sessionId,
        kind: 'artifact_directory',
        variantCount: assignedCount,
        durationMs: Date.now() - provisionStartedAt,
      });
    }
  }

  readArtifact(
    sessionId: string,
    workItemId: string,
  ): { html: string; assetBase: string } {
    if (!this.deps.inventory.hasSession(sessionId)) {
      throw new AgentVariantsError(
        'SESSION_NOT_FOUND',
        `No live resources for session ${sessionId}`,
      );
    }
    return this.deps.inventory.readArtifact(sessionId, workItemId);
  }

  async provisionAppended(
    sessionId: string,
    workItemIds: string[],
  ): Promise<void> {
    if (workItemIds.length === 0) return;
    await this.withTelemetry(
      {
        sessionId,
        kind: 'appended_existing',
        variantCount: workItemIds.length,
      },
      async () => {
        const paths = await withProvisionTimeout(
          this.deps.worktreeManager.createWorktrees(
            sessionId,
            workItemIds.length,
            `a${randomUUID().slice(0, 8)}-`,
            { requiredProjectFiles: await this.staticEntryFiles(sessionId) },
          ),
          this.deps.provisionTimeoutMs,
        );
        await Promise.all(
          workItemIds.map((workItemId, index) =>
            this.deps.inventory.registerWorktree(sessionId, {
              workItemId,
              worktreePath: paths[index],
            }),
          ),
        );
      },
    );
  }

  async provisionForked(
    sessionId: string,
    sourceVariantId: string,
    workItemIds: string[],
  ): Promise<void> {
    if (workItemIds.length === 0) return;
    const sourcePath = this.deps.inventory.getWorktree(
      sessionId,
      sourceVariantId,
    )?.worktreePath;
    if (!sourcePath) {
      throw new AgentVariantsError(
        'VARIANT_NOT_EDITABLE',
        `Cannot fork from variant ${sourceVariantId}: no worktree path`,
      );
    }
    const fork = this.deps.worktreeManager.forkWorktreesFrom?.bind(
      this.deps.worktreeManager,
    );
    if (!fork) {
      throw new AgentVariantsError(
        'RUNTIME_VALIDATION_FAILED',
        'worktreeManager does not implement forkWorktreesFrom',
      );
    }
    await this.withTelemetry(
      { sessionId, kind: 'forked_variant', variantCount: workItemIds.length },
      async () => {
        const paths = await withProvisionTimeout(
          fork(
            sourcePath,
            sessionId,
            workItemIds.length,
            `f${randomUUID().slice(0, 8)}-`,
          ),
          this.deps.provisionTimeoutMs,
        );
        await Promise.all(
          workItemIds.map((workItemId, index) =>
            this.deps.inventory.registerWorktree(sessionId, {
              workItemId,
              worktreePath: paths[index],
            }),
          ),
        );
      },
    );
  }

  async provision(
    sessionId: string,
    approveResult: ApproveResult,
  ): Promise<void> {
    const projectContext = this.deps.store.getProjectContext(sessionId);
    if (resolveRunPlanPolicy(projectContext).provision === 'none') return;
    const variantCount =
      approveResult.codeGenWorkItemIds.length +
      (approveResult.scaffoldBaseWorkItemId ? 1 : 0);
    try {
      await this.withTelemetry(
        { sessionId, kind: projectContext.kind, variantCount },
        async () => {
          if (projectContext.kind === 'fresh') {
            await this.provisionFresh(sessionId, approveResult, projectContext);
          } else {
            await this.provisionExisting(sessionId, approveResult);
          }
        },
        this.deps.provisionTimeoutMs,
      );
    } catch (error) {
      void this.deps.cancelSession(sessionId).catch((cleanupError) => {
        log.warn(
          `cleanup after provisioning failure for ${sessionId} failed`,
          cleanupError,
        );
      });
      if (error instanceof ProvisionTimeoutError) {
        throw new AgentVariantsError(
          'RUNTIME_VALIDATION_FAILED',
          `Provisioning ${variantCount} variant worktree(s) timed out after ` +
            `${Math.round(this.deps.provisionTimeoutMs / 1000)}s. This usually means the ` +
            `project is very large or slow to clone (e.g. a big monorepo, or a ` +
            `React Native tree with native build dirs that aren't git-ignored). ` +
            `Try git-ignoring build artifacts, or generate standalone variants ` +
            `with start_variants(mode='zero_to_one') instead of cloning this project.`,
        );
      }
      throw error;
    }
  }

  private async provisionExisting(
    sessionId: string,
    approveResult: ApproveResult,
  ): Promise<void> {
    const workItemIds = [
      ...(approveResult.scaffoldBaseWorkItemId
        ? [approveResult.scaffoldBaseWorkItemId]
        : []),
      ...approveResult.codeGenWorkItemIds,
    ];
    if (workItemIds.length === 0) return;
    const paths = await this.deps.worktreeManager.createWorktrees(
      sessionId,
      workItemIds.length,
      '',
      { requiredProjectFiles: await this.staticEntryFiles(sessionId) },
    );
    if (approveResult.scaffoldBaseWorkItemId) {
      this.deps.inventory.setScaffoldBaseWorkItemId(
        sessionId,
        approveResult.scaffoldBaseWorkItemId,
      );
    }
    await Promise.all(
      workItemIds.map((workItemId, index) =>
        this.deps.inventory.registerWorktree(sessionId, {
          workItemId,
          worktreePath: paths[index],
        }),
      ),
    );
  }

  private async staticEntryFiles(sessionId: string): Promise<string[]> {
    try {
      const environment = await this.deps.resolveProjectEnvironment(sessionId);
      return environment.framework === 'static' && environment.entryPath
        ? [environment.entryPath]
        : [];
    } catch (error) {
      log.warn(
        `Failed to resolve the static entry for ${sessionId}; worktrees carry only files git tracks or leaves untracked`,
        error,
      );
      return [];
    }
  }

  private async provisionFresh(
    sessionId: string,
    approveResult: ApproveResult,
    projectContext: ProjectContext & { kind: 'fresh' },
  ): Promise<void> {
    const scaffoldId = approveResult.scaffoldBaseWorkItemId;
    if (!scaffoldId) {
      throw new AgentVariantsError(
        'INVALID_STAGE_ACTION',
        `Fresh session ${sessionId} approved without a scaffold_base item`,
      );
    }
    const workItemIds = approveResult.codeGenWorkItemIds;
    if (workItemIds.length === 0) return;
    const createFresh = this.deps.worktreeManager.createFreshWorktrees;
    if (!createFresh) {
      throw new AgentVariantsError(
        'RUNTIME_VALIDATION_FAILED',
        'worktreeManager does not implement createFreshWorktrees',
      );
    }
    const designContext = projectContext.designContext
      ? workItemIds.map(
          (workItemId) =>
            this.deps.store.getVariantWorkItemInput(sessionId, workItemId)
              ?.designContextEntry,
        )
      : undefined;
    const scaffoldStartedAt = Date.now();
    trackScaffoldStarted(this.deps.telemetry, {
      sessionId,
      variantCount: workItemIds.length,
      designContext: summarizeDesignContext(designContext),
    });
    const paths = await createFresh.call(
      this.deps.worktreeManager,
      sessionId,
      workItemIds.length,
      VITE_REACT_TS_TEMPLATE,
      designContext,
      projectContext.workspaceRoot,
    );
    this.deps.inventory.setScaffoldBaseWorkItemId(sessionId, scaffoldId);
    this.deps.inventory.setFreshDestinationParent(
      sessionId,
      projectContext.workspaceRoot,
    );
    await Promise.all(
      workItemIds.map((workItemId, index) =>
        this.deps.inventory.registerWorktree(sessionId, {
          workItemId,
          worktreePath: paths[index],
        }),
      ),
    );
    try {
      for (const worktreePath of paths) {
        for (const entry of projectContext.executionPlan?.assetPlan ?? []) {
          copyAssetIntoWorktree(
            worktreePath,
            entry,
            projectContext.assetSourceRoot,
          );
        }
      }
    } catch (error) {
      this.failScaffold(sessionId, scaffoldId, scaffoldStartedAt, error);
      return;
    }
    void this.installFreshDependencies(
      sessionId,
      scaffoldId,
      paths,
      scaffoldStartedAt,
    ).catch((error) => {
      log.error(
        `installFreshDependencies failed for session ${sessionId}`,
        error,
      );
    });
  }

  private async installFreshDependencies(
    sessionId: string,
    scaffoldId: string,
    worktreePaths: string[],
    scaffoldStartedAt: number,
  ): Promise<void> {
    const installStartedAt = Date.now();
    try {
      await Promise.all(
        worktreePaths.map((worktreePath) =>
          this.deps.installDependencies(worktreePath, {
            workspaceRoot: worktreePath,
            signal: this.deps.inventory.getDependencySignal(sessionId),
          }),
        ),
      );
    } catch (error) {
      if (
        !this.deps.isSessionLive(sessionId) ||
        this.deps.inventory.isCleanupStarted(sessionId)
      ) {
        return;
      }
      this.failScaffold(sessionId, scaffoldId, scaffoldStartedAt, error);
      return;
    }
    try {
      this.deps.store.completeInternal({
        sessionId,
        workItemId: scaffoldId,
        output: { worktreePaths },
      });
      this.deps.changed();
    } catch (error) {
      log.warn(`completeInternal failed for ${sessionId}/${scaffoldId}`, error);
    }
    trackScaffoldCompleted(this.deps.telemetry, {
      sessionId,
      durationMs: Date.now() - scaffoldStartedAt,
      installDurationMs: Date.now() - installStartedAt,
      variantCount: worktreePaths.length,
    });
  }

  private failScaffold(
    sessionId: string,
    scaffoldId: string,
    scaffoldStartedAt: number,
    error: unknown,
  ): void {
    trackScaffoldFailed(this.deps.telemetry, {
      sessionId,
      errorCode: 'SCAFFOLD_FAILED',
      durationMs: Date.now() - scaffoldStartedAt,
    });
    try {
      this.deps.store.failInternal({
        sessionId,
        workItemId: scaffoldId,
        error: {
          code: 'SCAFFOLD_FAILED',
          message: errorMessage(error),
        },
      });
      this.deps.changed();
    } catch (storeError) {
      log.error(
        `failInternal failed for ${sessionId}/${scaffoldId}`,
        storeError,
      );
    }
  }

  private async withTelemetry<T>(
    args: { sessionId: string; kind: string; variantCount: number },
    run: () => Promise<T>,
    timeoutMs?: number,
  ): Promise<T> {
    const startedAt = Date.now();
    this.deps.telemetry.track('agent_variants.provisioning_started', {
      source: 'mcp',
      ...args,
    });
    try {
      const result = await (timeoutMs
        ? withProvisionTimeout(run(), timeoutMs)
        : run());
      this.deps.telemetry.track('agent_variants.provisioning_completed', {
        source: 'mcp',
        ...args,
        durationMs: Date.now() - startedAt,
      });
      return result;
    } catch (error) {
      this.deps.telemetry.track('agent_variants.provisioning_failed', {
        source: 'mcp',
        ...args,
        durationMs: Date.now() - startedAt,
        timedOut: error instanceof ProvisionTimeoutError,
        errorCode:
          error instanceof ProvisionTimeoutError
            ? 'PROVISION_TIMEOUT'
            : error instanceof AgentVariantsError
              ? error.code
              : 'PROVISION_FAILED',
        ...(error instanceof GitCommandError
          ? { ...failureReason(error), gitCommand: error.gitCommand }
          : { reasonCode: failureReasonCode(error) }),
      });
      throw error;
    }
  }
}
